private persistRequestBody(purchaseId: PurchaseId, intent: PurchaseIntent): void {
  const body = intent.resource.body ?? new Uint8Array();
  this.journal.storeEvidence(purchaseId, {
    bytes: body,
    mediaType: intent.resource.mediaType ?? "application/octet-stream",
    profile: REQUEST_BODY_PROFILE,
    issuer: "purchase-intent",
    kind: "purchase-request-body",
  });

store(bytes: Uint8Array): StoredEvidence {
  this.assertDirectoryUnchanged();
  const content = Buffer.from(bytes);
  const digest = evidenceDigest(content);
  const stored = this.referenceFor(digest, content.byteLength);
  const target = this.pathFor(stored.storageRef);

  if (pathExists(target)) {
    const existing = this.read(digest, content.byteLength);
    if (!existing.equals(content)) {
      throw new EvidenceStoreError("existing evidence bytes do not match their content address");
    }
    return stored;
  }

  const temporary = path.join(
    this.directory,
    `${TEMP_PREFIX}${process.pid}-${randomBytes(16).toString("hex")}`
  );
  let temporaryExists = false;

  try {
    const descriptor = fs.openSync(
      temporary,
      fs.constants.O_WRONLY |
        fs.constants.O_CREAT |
        fs.constants.O_EXCL |
        noFollowFlag(),
      FILE_MODE
    );
    temporaryExists = true;
    try {
      fs.fchmodSync(descriptor, FILE_MODE);
      fs.writeFileSync(descriptor, content);
      fs.fsyncSync(descriptor);
    } finally {
      fs.closeSync(descriptor);
    }

    this.assertDirectoryUnchanged();
    if (pathExists(target)) {
      const existing = this.read(digest, content.byteLength);
      if (!existing.equals(content)) {
        throw new EvidenceStoreError("concurrent evidence bytes do not match their content address");
      }
      fs.unlinkSync(temporary);
      temporaryExists = false;
      fsyncDirectory(this.directory);
      return stored;
    }

    fs.renameSync(temporary, target);
    temporaryExists = false;
    fsyncDirectory(this.directory);

    const persisted = this.read(digest, content.byteLength);
    if (!persisted.equals(content)) {
      throw new EvidenceStoreError("persisted evidence bytes changed during atomic storage");
    }
    return stored;

storeEvidence(purchaseId: PurchaseId, input: StoreEvidenceInput): EvidenceAttachmentRecord {
  validateEvidenceMetadata(input);
  if (!this.evidenceStore) {
    throw new JournalInvariantError("an evidence directory is required for immutable evidence storage");
  }
  const stored = this.evidenceStore.store(input.bytes);
  const attach = this.db.transaction(() => {
    this.requirePurchase(purchaseId);
    if (input.attempt !== undefined) this.requirePaymentAttempt(purchaseId, input.attempt);
    const existing = this.findEvidence(stored.digest);
    if (existing) {
      assertSameEvidenceBlob(existing, stored.byteLength, stored.storageRef);
    } else {
      const now = this.timestamp();
      this.db
        .prepare(
          `INSERT INTO evidence_artifacts
             (digest, media_type, profile, issuer, byte_length, storage_ref, created_at_ms)
           VALUES (?, ?, ?, ?, ?, ?, ?)`
        )
        .run(
          stored.digest,
          "application/octet-stream",
          "urn:sompi:evidence-blob:1",
          null,
          stored.byteLength,
          stored.storageRef,
          now
        );
      this.inject("evidence.after_metadata_insert");
    }
    const attachedAtMs = this.timestamp();
    this.db
      .prepare(
        `INSERT OR IGNORE INTO evidence_links
           (purchase_id, digest, kind, attempt, media_type, profile, issuer, attached_at_ms)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      )
      .run(
        purchaseId,
        stored.digest,
        input.kind,
        input.attempt ?? null,
        input.mediaType,
        input.profile,
        input.issuer ?? null,
        attachedAtMs
      );
    const attachment = this.requireEvidenceAttachment(
      purchaseId,
      stored.digest,
      input.kind,
      input.attempt
    );
    assertSameEvidenceAttachment(attachment, input);
    return attachment;
  });
